import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const _=JSON.parse(`{"title":"麦当劳 McDonald's Corporation","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/麦当劳.md","filePath":"03_companies/麦当劳.md"}`),n={name:"03_companies/麦当劳.md"};function i(l,a,s,c,d,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="麦当劳-mcdonald-s-corporation" tabindex="-1">麦当劳 McDonald&#39;s Corporation <a class="header-anchor" href="#麦当劳-mcdonald-s-corporation" aria-label="Permalink to &quot;麦当劳 McDonald&#39;s Corporation&quot;">​</a></h1><h2 id="公司简介" tabindex="-1">公司简介 <a class="header-anchor" href="#公司简介" aria-label="Permalink to &quot;公司简介&quot;">​</a></h2><p>麦当劳是全球最大的快餐连锁企业，以标准化运营和特许经营模式著称，在全球100多个国家拥有数万家餐厅。公司通过&quot;房地产+品牌&quot;的独特特许经营模式，实现了低成本快速扩张。巴菲特长期观察麦当劳，但始终未将其纳入伯克希尔核心持仓。</p><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><ul><li><strong>1990年代</strong>：巴菲特多次公开表示关注麦当劳，但未买入</li><li><strong>长期观察期</strong>：伯克希尔持续追踪麦当劳的经营数据</li><li><strong>最终决定</strong>：经过多年评估，巴菲特认为估值不足以支撑投资</li><li><strong>2017年后</strong>：市场传言伯克希尔有买入意向，但未得到官方确认</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特对麦当劳的特许经营模式给予了高度认可。他多次在股东信中称赞麦当劳是&quot;真正的特许经营冠军&quot;——麦当劳并不拥有所有餐厅的物业，而是通过租约和特许经营协议控制了庞大的门店网络，这种轻资产模式带来了极高的资本回报率。</p><p>然而，巴菲特迟迟不投资麦当劳的原因主要在于估值。他曾表示，麦当劳的股价在大多数时候都反映了其卓越的经营成果，也就是说，市场并没有给投资者留出足够的安全边际。巴菲特宁愿等待一个更有吸引力的价格，也不愿为一家好公司支付过高的代价。另一个考量是，麦当劳面临日益激烈的快餐竞争，健康饮食趋势对长期品牌价值的侵蚀也令他保持警惕。</p><h2 id="关键语录" tabindex="-1">关键语录 <a class="header-anchor" href="#关键语录" aria-label="Permalink to &quot;关键语录&quot;">​</a></h2><blockquote><p>&quot;麦当劳是一家卓越的企业，拥有真正的特许经营护城河。但好公司也需要有好价格。如果一家优秀企业的估值已经充分反映了其竞争优势，那么投资者就失去了安全边际。在投资中，耐心等待好价格与挑选好公司同样重要。&quot;</p></blockquote>',10)])])}const u=o(n,[["render",i]]);export{_ as __pageData,u as default};
